{
  "name": "anthropic-sdk-mocked-tool-use",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --import tsx --test test/*.test.ts"
  },
  "dependencies": {
    "@anthropic-ai/sdk": "0.134.0",
    "zod": "4.6.7"
