import os
import stripe
from fastapi import FastAPI, Header, HTTPException, Request

app = FastAPI()
WEBHOOK_SECRET = os.environ.get("STRIPE_WEBHOOK_SECRET", "whsec_test")
handled: list[str] = []

@app.post("/webhooks/stripe")
async def stripe_webhook(request: Request, stripe_signature: str | None = Header(default=None)):
    if not stripe_signature:
        raise HTTPException(400, "missing signature")
    payload = await request.body()  # raw bytes, never re-serialized JSON
    try:
        event = stripe.Webhook.construct_event(payload, stripe_signature, WEBHOOK_SECRET)
    except (ValueError, stripe.SignatureVerificationError):
        raise HTTPException(400, "bad signature")
    if event["type"] == "checkout.session.completed":
        handled.append(event["data"]["object"]["id"])
    return {"received": True, "type": event["type"]}

from fastapi import FastAPI, WebSocket, WebSocketDisconnect, status

app = FastAPI()
TOKENS = {"t-ada": "ada", "t-bob": "bob"}

class Hub:
    def __init__(self):
        self.clients: dict[WebSocket, str] = {}

    async def broadcast(self, data: dict):
        for ws in list(self.clients):
            await ws.send_json(data)

hub = Hub()

@app.websocket("/ws")
async def ws_endpoint(websocket: WebSocket, token: str = ""):
    user = TOKENS.get(token)
    if not user:
        await websocket.close(code=status.WS_1008_POLICY_VIOLATION)
        return
    await websocket.accept()
    hub.clients[websocket] = user
    try:
        while True:
            msg = await websocket.receive_json()
            await hub.broadcast({"from": user, "text": msg.get("text", "")})
    except WebSocketDisconnect:
        hub.clients.pop(websocket, None)

