import httpx
from pydantic import BaseModel

class Repo(BaseModel):
    id: int
    full_name: str
    stargazers_count: int

class ApiClient:
    def __init__(self, base_url: str = "https://api.example.com", retries: int = 2):
        self.http = httpx.AsyncClient(base_url=base_url, timeout=10)
        self.retries = retries

    async def get_repo(self, owner: str, name: str) -> Repo:
        for attempt in range(self.retries + 1):
            r = await self.http.get(f"/repos/{owner}/{name}")
            if r.status_code < 500 or attempt == self.retries:
                break
        r.raise_for_status()
        return Repo.model_validate(r.json())

    async def aclose(self):
        await self.http.aclose()

import httpx
from tenacity import retry, retry_if_exception, stop_after_attempt, wait_exponential

def _transient(exc: BaseException) -> bool:
    if isinstance(exc, (httpx.TimeoutException, httpx.ConnectError)):
        return True
    return isinstance(exc, httpx.HTTPStatusError) and (exc.response.status_code == 429 or exc.response.status_code >= 500)

class ApiClient:
    def __init__(self, base_url: str, attempts: int = 4, wait_max: float = 8.0):
        self.http = httpx.Client(base_url=base_url, timeout=5.0)
        self._get = retry(
            retry=retry_if_exception(_transient),
            stop=stop_after_attempt(attempts),
            wait=wait_exponential(multiplier=0.5, max=wait_max),
            reraise=True,  # surface the real httpx error, not tenacity.RetryError
        )(self._get_once)

    def _get_once(self, path: str):
        r = self.http.get(path)
        r.raise_for_status()
        return r.json()

    def get_json(self, path: str):
        return self._get(path)

